  'black-wednesday.mc-who-lost.option.germany.label': 'El Bundesbank',
  'black-wednesday.match-preconditions.prompt': 'Hoy estás analizando otra moneda con tipo de cambio fijo. Relaciona cada cosa que debes comprobar con lo que te dice.',
